// --- 1. INITIAL SETUP ---
$ctrl.currentPage = page ?? $ctrl.currentPage;
$ctrl.isLoading = true;
$ctrl.displayTable = false;
$ctrl.tableData = [];
$ctrl.relationshipData = [];

try {
    const apiRelatedEntityType = $ctrl.currentRelatedEntity.type === "Deal" ? "Opportunity" : $ctrl.currentRelatedEntity.type;
    const lowercasedApiRelatedEntityType = apiRelatedEntityType.toLowerCase();
    const primaryEntityId = $ctrl.primaryEntity?.[$ctrl.primaryEntityType + "Id"]?.toString();
    const isLinking = $ctrl.currentAction?.buttonLabel === "LINK";

    // --- 2. FETCH & PROCESS RELATIONSHIPS ---
    // Fetch all existing relationships for the primary entity in parallel.
    $ctrl.relationshipData = await _fetchEntityRelationships(primaryEntityId, apiRelatedEntityType);

    // Create a lookup map of { relatedEntityId -> relationshipObject }.
    const relatedEntityMap = _buildRelatedEntityMap($ctrl.relationshipData, primaryEntityId);
    const relatedEntityIds = [...relatedEntityMap.keys()];

    // --- 3. HANDLE EARLY EXIT ---
    // If unlinking/editing but there are no relationships, show an empty table.
    if (!isLinking && relatedEntityIds.length === 0) {
        $ctrl.currentTotalPages = 1;
        $ctrl.displayTable = true;
        return;
    }

    // --- 4. BUILD THE MAIN ENTITY QUERY ---
    // Abstract the complex query string logic into a helper.
    const entityQuery = _buildRelationshipQuery({
        isLinking,
        lowercasedApiRelatedEntityType,
        relatedEntityIds,
        primaryEntityId,
        externalQuery: query
    });

    // --- 5. FETCH THE TARGET ENTITIES (e.g., Contacts, Companies) ---
    let effectiveLimit = limit ?? 25;
    const { entities, total, totalFiltered } = await $ctrl.entityService.getAllEntities({
        page: $ctrl.currentPage,
        limit: effectiveLimit,
        query: entityQuery,
        clearCache,
        entity: lowercasedApiRelatedEntityType
    });

    // --- 6. ENRICH DATA & UPDATE STATE ---
    if (totalFiltered) {
        $ctrl.currentTotalPages = Math.ceil(totalFiltered / effectiveLimit);
    } else {
        $ctrl.currentTotalPages = 1;
    }

    const relatedEntityIdKey = `${lowercasedApiRelatedEntityType}Id`;

    // Create a lookup map of the user's currently selected/modified rows
    const localSelectionMap = new Map();
    if ($ctrl.selectedRowsForRelationship && $ctrl.selectedRowsForRelationship.length > 0) {
        $ctrl.selectedRowsForRelationship.forEach(row => {
            if (row[relatedEntityIdKey]) {
                localSelectionMap.set(row[relatedEntityIdKey].toString(), row);
            }
        });
    }

    $ctrl.tableData = entities.map(entity => {
        const entityIdStr = entity[relatedEntityIdKey]?.toString();
        let activeRelationshipType;

        // Has the user selected/edited this locally?
        if (localSelectionMap.has(entityIdStr)) {
            // If so, use that relationship value
            activeRelationshipType = localSelectionMap.get(entityIdStr).relationshipType;
        }
        else {
            // Otherwise, use original relationship value
            activeRelationshipType = relatedEntityMap.get(entityIdStr)?.relationshipType;
        }

        return {
            ...entity,
            relationshipType: activeRelationshipType
        };
    });

    $ctrl.displayTable = true;
    $ctrl.$timeout(() => {
        $ctrl.initializeGridListener(relatedEntityIdKey);
        _syncGridSelection(relatedEntityIdKey);
    }, 100);

} catch (error) {
    console.error(`Error fetching relationship data:`, error);
    $ctrl.utilityService.toast("Failed to load relationship data.", "ERROR");
} finally {
    $ctrl.isLoading = false;
}

/**
 * Fetches both direct and inverse relationships for a given entity in parallel.
 * @private
 */
async function _fetchEntityRelationships(primaryEntityId, apiRelatedEntityType) {
    if (!primaryEntityId) return [];

    const uppercasedPrimaryEntityType = $ctrl.primaryEntityType?.[0]?.toUpperCase() + $ctrl.primaryEntityType?.slice(1);
    _setFilterColumnValuesAndNameColumnValue(apiRelatedEntityType);

    const [direct, inverse] = await Promise.all([
        $ctrl.entityService.getAllEntities({
            limit: "ALL",
            query: `primaryEntityType=${uppercasedPrimaryEntityType}&primaryEntityId=${primaryEntityId}&relatedEntityType=${apiRelatedEntityType}`,
            entity: "relationship"
        }),
        $ctrl.entityService.getAllEntities({
            limit: "ALL",
            query: `relatedEntityType=${uppercasedPrimaryEntityType}&relatedEntityId=${primaryEntityId}&primaryEntityType=${apiRelatedEntityType}`,
            entity: "relationship"
        })
    ]);

    // The service returns { entities, ... }, so we need to access the entities array.
    return [...(direct.entities || []), ...(inverse.entities || [])];
}

/**
 * Creates a Map of { relatedEntityId -> relationshipObject } for quick lookups.
 * @private
 */
function _buildRelatedEntityMap(allRelationships, primaryEntityId) {
    const relatedEntityMap = new Map();
    for (const rel of allRelationships) {
        const pId = rel.primaryEntityId?.toString();
        const rId = rel.relatedEntityId?.toString();
        // Determine which ID is the "other" one.
        const relatedId = pId === primaryEntityId ? rId : pId;
        if (relatedId) {
            relatedEntityMap.set(relatedId, rel);
        }
    }
    return relatedEntityMap;
}

/**
 * Constructs the final query string for fetching target entities.
 * @private
 */
function _buildRelationshipQuery({ isLinking, lowercasedApiRelatedEntityType, relatedEntityIds, primaryEntityId, externalQuery }) {
    const idKey = `${lowercasedApiRelatedEntityType}Id`;
    let idFilter = '';

    // Create a list of all IDs to exclude when linking (related IDs + the primary entity's ID if types match)
    const idsToFilter = [...relatedEntityIds];
    if (isLinking && lowercasedApiRelatedEntityType === $ctrl.primaryEntityType) {
        idsToFilter.push(primaryEntityId);
    }

    if (idsToFilter.length > 0) {
        idFilter = isLinking
            ? `${idKey}_notin=${idsToFilter.join(',')}`
            : `${idKey}_in=${idsToFilter.join(',')}`;
    }

    // Combine the ID filter with any external search query.
    if (idFilter && externalQuery) return `${idFilter}&${externalQuery}`;
    return idFilter || externalQuery || undefined;
}

/**
 * Helper function to synchronize the ui-grid's selected rows with a master list.
 * @private
 */
function _syncGridSelection(relatedEntityIdKey) {
    // Get the parent scope that contains the controller instance
    const scope = angular.element(document.querySelectorAll('.bln-table')[1]).scope().$parent;
    const ctrl = scope.$ctrl;
    const gridApi = ctrl.gridApi;

    if (!$ctrl.selectedRowsForRelationship || $ctrl.selectedRowsForRelationship.length === 0 || !gridApi) {
        return;
    }

    // Use the grid's 'rowsRendered' event to reliably wait for the grid to be ready.
    const deregisterEvent = gridApi.core.on.rowsRendered(null, () => {
        const selectedIds = new Set($ctrl.selectedRowsForRelationship.map(row => row[relatedEntityIdKey]));

        gridApi.grid.rows.forEach(row => {
            if (selectedIds.has(row.entity[relatedEntityIdKey])) {
                gridApi.selection.selectRow(row.entity);
            }
        });

        deregisterEvent(); // Clean up the event listener.
    });

    gridApi.core.refresh();
}

function _setFilterColumnValuesAndNameColumnValue(apiRelatedEntityType) {
    switch (apiRelatedEntityType) {
        case "Contact":
            $ctrl.currentFilter.columnValues = $ctrl.contactService.getFilterColumnValues();
            $ctrl.nameColumnValue = "fullName";
            break;
        case "Company":
            $ctrl.currentFilter.columnValues = $ctrl.companyService.getFilterColumnValues();
            $ctrl.nameColumnValue = "name";
            break;
        case "Opportunity":
            $ctrl.currentFilter.columnValues = $ctrl.opportunityService.getFilterColumnValues();
            $ctrl.nameColumnValue = "name";
            break;
    }
}

const actionMap = {
    "Create New Links": "LINK",
    "Edit Existing Links": "EDIT",
    "Remove Existing Links": "UNLINK"
};

$ctrl.currentAction.label = label;
$ctrl.currentAction.icon = icon;
$ctrl.currentAction.buttonLabel = actionMap[label];

$ctrl.currentPage = 1;

$ctrl.isInitialLoad = true;
$ctrl.loadData(undefined, undefined, $ctrl.currentFilter.query, undefined);

try {
    if ($ctrl.isLoading) return;

    $ctrl.currentRelatedEntity.type = type;
    $ctrl.currentRelatedEntity.icon = icon;
    $ctrl.displayTable = false;

    $ctrl.onCancelButtonClick();
} catch (error) {
    console.error("An error occurred in watchCurrentTab:", error);
}

if (!newColumnValue && !newOperationValue && !newTargetValue) {
    const { column, operation, target } = $ctrl.currentFilter;
    $ctrl.currentFilter = {
        column: null,
        operation: null,
        target: null,
        query: '',
        columnValues: $ctrl.currentFilter.columnValues
    }

    if (!column || !operation || !target) return;

    $ctrl.loadData(1, undefined, null, undefined);
    return;
}

$ctrl.currentFilter.column = newColumnValue ?? $ctrl.currentFilter.column;
$ctrl.currentFilter.operation = newOperationValue ?? $ctrl.currentFilter.operation;
$ctrl.currentFilter.target = newTargetValue ?? $ctrl.currentFilter.target;

if (newTargetValue === "") {
    $ctrl.currentFilter.query = undefined;
    $ctrl.loadData(undefined, undefined, undefined, undefined);
}

if (!($ctrl.currentFilter.column && $ctrl.currentFilter.operation && $ctrl.currentFilter.target)) return;

$ctrl.currentFilter.query = buildFilterQuery($ctrl.currentFilter);

$ctrl.loadData(1, undefined, $ctrl.currentFilter.query, undefined);

function buildFilterQuery(currentFilter) {
    if (!currentFilter || !currentFilter.column || !currentFilter.target || !currentFilter.operation) {
        return '';
    }

    const { column, target, operation } = currentFilter;
    let apiOperation = operation;

    return `${column}_${apiOperation}=${target}`;
}

$ctrl.isLinking = true;
$ctrl.successfulLinks.length = 0;
$ctrl.failedLinks.length = 0;

const primaryEntityType = $ctrl.primaryEntityType[0].toUpperCase() + $ctrl.primaryEntityType.slice(1);
const primaryEntityIdKey = $ctrl.primaryEntityType + "Id";

const currentRelatedEntityType = $ctrl.currentRelatedEntity?.type;
const apiRelatedEntityType = (currentRelatedEntityType === "Deal") ? "Opportunity" : currentRelatedEntityType;
const lowercasedApiRelatedEntityType = apiRelatedEntityType?.toLowerCase();

const relatedEntityIdKey = lowercasedApiRelatedEntityType + "Id";
const primaryEntityId = $ctrl.primaryEntity?.[primaryEntityIdKey]?.toString();

const actionLabel = $ctrl.currentAction?.buttonLabel;

try {
    for (const row of $ctrl.selectedRowsForRelationship) {
        let requestMethod = "POST";
        let relationshipId;
        const entityName = row.fullName || row.name || "No identifier available";

        let requestBody = {
            relationshipType: row.relationshipType ?? "--",
            primaryEntityType: primaryEntityType,
            primaryEntityId: primaryEntityId,
            relatedEntityType: apiRelatedEntityType,
            relatedEntityId: row[relatedEntityIdKey]?.toString()
        };

        // --- Action-specific logic (EDIT/UNLINK) ---
        if (actionLabel === "EDIT" || actionLabel === "UNLINK") {
            // Find existing relationship using primary entity ID (current record) and related entity ID (row)
            const matchingRelationship = $ctrl.relationshipData?.find(rel => {
                // Both direct and inverse matches need to be checked
                // And ensure entity IDs are compared as strings
                const primaryIdMatch = rel.primaryEntityId?.toString() === primaryEntityId;
                const relatedIdMatch = rel.relatedEntityId?.toString() === requestBody.relatedEntityId; // This is the ID from the selected row

                // Case 1: Our primary entity is the primary in the existing relationship record
                const isDirectMatch = primaryIdMatch && relatedIdMatch;

                // Case 2: Our primary entity is the related in the existing relationship record,
                //         and the selected row's entity is the primary in the existing record.
                const isInverseMatch = rel.relatedEntityId?.toString() === primaryEntityId && rel.primaryEntityId?.toString() === requestBody.relatedEntityId;

                // If you expect `relationshipType` to also match for editing/unlinking a *specific* link, add:
                // && rel.relationshipType === requestBody.relationshipType
                return isDirectMatch || isInverseMatch;
            });

            relationshipId = matchingRelationship?.relationshipId;

            if (!relationshipId) {
                $ctrl.failedLinks.push({
                    name: entityName,
                    message: `Could not find existing relationship ID for ${actionLabel.toLowerCase()}.`,
                    action: actionLabel
                });
                continue; // Skip to the next row
            }

            if (actionLabel === "EDIT") {
                requestMethod = "PUT";
                requestBody = { ...requestBody, relationshipId: relationshipId };
            } else if (actionLabel === "UNLINK") {
                requestMethod = "DELETE";
                requestBody = null; // Explicitly set to null for DELETE
            }
        }
        // --- End Action-specific logic ---

        // --- API Call Execution ---
        let response;
        let apiEndpoint = "relationship";

        if (requestMethod === "DELETE") {
            const unlinkConfirmationLabel = `Relationship with ${entityName}`;
            const unlinkConfirmationData = { name: entityName, relationshipType: row.relationshipType };
            const entityDetailsForUnlink = $ctrl.utilityService.formatEntityForDisplay(unlinkConfirmationData);

            const deleteResult = await $ctrl.dataService.deleteData(apiEndpoint, relationshipId, {
                displayName: unlinkConfirmationLabel,
                modalData: entityDetailsForUnlink
            });

            if (deleteResult?.result === "cancel") {
                $ctrl.failedLinks.push({
                    name: entityName,
                    message: "Deletion cancelled by user.",
                    action: actionLabel
                });
                continue;
            }
            response = deleteResult;
        } else {
            response = await $ctrl.dataService.sendData(apiEndpoint, requestMethod, requestBody);
        }

        // --- Process API Response ---
        if (response && response.result === "OK") {
            $ctrl.successfulLinks.push({
                name: entityName,
                relationship: row.relationshipType,
                action: actionLabel || "LINK"
            });
        } else if (response && response.result === "ERROR") {
            $ctrl.failedLinks.push({
                name: entityName,
                message: response.message,
                action: actionLabel || "LINK"
            });
        } else {
            $ctrl.failedLinks.push({
                name: entityName,
                message: "Unexpected response format",
                action: actionLabel || "LINK"
            });
        }
    } // End of for loop

    $ctrl.selectedRowsForRelationship.length = 0;
    $ctrl.isLinking = false;
    $ctrl.hasOperationCompleted = true;

    await $ctrl.loadData();

} catch (error) {
    console.error(`An unexpected error occurred while ${actionLabel?.toLowerCase() || 'linking'} relationships:`, error);
    $ctrl.utilityService.toast(`An unexpected error occurred during relationship ${actionLabel?.toLowerCase() || 'linking'}`, "ERROR");
    $ctrl.isLinking = false;
}

const defaultFilter = {
    column: null,
    operation: null,
    target: null,
    query: null,
    columnValues: $ctrl.currentFilter.columnValues
}

$ctrl.currentPage = 1;
$ctrl.hasOperationCompleted = false;
$ctrl.currentFilter = { ...defaultFilter };
$ctrl.selectedRows.length = 0;

$ctrl.loadData();

// $ctrl.selectedRows.length = 0;
// $ctrl.selectedRowsForRelationship.length = 0;

// Get the parent scope that contains the controller instance
const scope = angular.element(document.querySelectorAll('.bln-table')[1]).scope().$parent;

// Get the controller instance and gridApi from that scope's controller.
// We use 'ctrl' inside the event handlers to refer to the controller instance,
// as '$ctrl' would have a different context inside the function callbacks.
const gridApi = scope.$ctrl.gridApi;

// --- Register the listener for single row selection ---
gridApi.selection.on.rowSelectionChanged(scope, function (row) {
    // 'row.entity' is the data object for the row that changed.
    // 'row.isSelected' tells you its new state.

    if (row.isSelected) {
        // --- ADD TO MASTER LIST ---z
        // Check if the row is already in the master list to avoid duplicates.
        const isAlreadySelected = $ctrl.selectedRowsForRelationship.some(selectedRow => selectedRow[relatedEntityIdKey] === row.entity[relatedEntityIdKey]);
        if (!isAlreadySelected) {
            $ctrl.selectedRowsForRelationship.push(row.entity);
        }

    } else {
        // --- REMOVE FROM MASTER LIST ---
        // Find the index of the deselected row in the master list and remove it.
        const indexToRemove = $ctrl.selectedRowsForRelationship.findIndex(selectedRow => selectedRow[relatedEntityIdKey] === row.entity[relatedEntityIdKey]);
        if (indexToRemove > -1) {
            $ctrl.selectedRowsForRelationship.splice(indexToRemove, 1);
        }
    }

});

// --- Register the listener for "Select All" (batch) selection ---
gridApi.selection.on.rowSelectionChangedBatch(scope, function (rows) {
    // 'rows' is an array of all the rows on the current page that were changed.

    if (rows.length > 0 && rows[0].isSelected) {
        // --- ADD BATCH TO MASTER LIST ---
        // User clicked "Select All" for the current page.
        const selectedIds = new Set($ctrl.selectedRowsForRelationship.map(r => r[relatedEntityIdKey]));
        rows.forEach(row => {
            // Add only if it's not already in the master list.
            if (!selectedIds.has(row.entity[relatedEntityIdKey])) {
                $ctrl.selectedRowsForRelationship.push(row.entity);
            }
        });
    } else {
        // --- REMOVE BATCH FROM MASTER LIST ---
        // User clicked "Deselect All" for the current page.
        const deselectedIdsOnPage = new Set(rows.map(r => r.entity[relatedEntityIdKey]));
        $ctrl.selectedRowsForRelationship = $ctrl.selectedRowsForRelationship.filter(
            selectedRow => !deselectedIdsOnPage.has(selectedRow[relatedEntityIdKey])
        );
    }
});
